const { authenticate } = await import('./index');

describe('auth/index', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockGetDefaultAuthenticatedRoles.mockReturnValue([]);
    mockGetUnauthenticatedRoles.mockReturnValue([]);
  });

  test('returns unauthenticated context when session has no user', async () => {
    const session = { authToken: 'token', expiresAt: new Date(), userId: null };
    mockObtainSession.mockResolvedValue(session as never);
    const roles = ['guest'];
    mockGetUnauthenticatedRoles.mockReturnValue(roles);

    const result = await authenticate(null);

    expect(result.session).toEqual(session);
    expect(result.user).toBeNull();
    expect(result.roles).toBe(roles);
    expect(mockFindOne).not.toHaveBeenCalled();
  });

  test('maps database user info when session has userId', async () => {
    const userId = new ObjectId('507f1f77bcf86cd799439011');
    const session = {
      authToken: 'token',
      expiresAt: new Date(),
      userId,
    };
    mockObtainSession.mockResolvedValue(session as never);
    const userDoc = {
      _id: userId,
      handle: 'demo',
      roles: ['admin'],
      createdAt: new Date(),
      authMethods: {},
    };
    mockFindOne.mockResolvedValue(userDoc as never);
    mockGetDefaultAuthenticatedRoles.mockReturnValue(['authenticated']);

    const result = await authenticate('token');

    expect(mockFindOne).toHaveBeenCalled();
    expect(result.user?.id).toBe(String(userDoc._id));
    expect(result.user?.handle).toBe('demo');
    expect(result.roles).toEqual(['authenticated']);

    expect(result.user?.hasRole('admin')).toBe(true);
    expect(() => result.user?.requireRole('missing')).toThrow(
      "Access denied - role 'missing' required"
    );
  });
});

import { describe, test, expect, beforeEach, jest } from '@jest/globals';

describe('authConfig', () => {
  beforeEach(() => {
    jest.resetModules();
  });

  test('returns a frozen empty config by default', async () => {
    const { getAuthConfig } = await import('./authConfig');

    const config = getAuthConfig();

    expect(config).toEqual({});
    expect(Object.isFrozen(config)).toBe(true);
  });

  test('merges new config properties while preserving previous ones', async () => {
    const { setAuthConfig, getAuthConfig } = await import('./authConfig');

    const onAfterLogin = jest.fn();
    setAuthConfig({ onAfterLogin });

    const onSignupError = jest.fn();
    setAuthConfig({ onSignupError });

    const config = getAuthConfig();

    expect(config).toMatchObject({ onAfterLogin, onSignupError });
    expect(Object.isFrozen(config)).toBe(true);
  });

  test('later updates override existing keys and create a new frozen object', async () => {
    const { setAuthConfig, getAuthConfig } = await import('./authConfig');

    const firstHandler = jest.fn();
    setAuthConfig({ onAfterLogin: firstHandler });
    const previousConfig = getAuthConfig();

    const secondHandler = jest.fn();
    setAuthConfig({ onAfterLogin: secondHandler });

    const updatedConfig = getAuthConfig();

    expect(updatedConfig.onAfterLogin).toBe(secondHandler);
    expect(updatedConfig).not.toBe(previousConfig);
    expect(Object.isFrozen(updatedConfig)).toBe(true);
  });
});

